package dev.aragonite.powersync.client;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.Settings;import android.widget.*;import org.json.*;import java.util.concurrent.*;
public final class MainActivity extends Activity {
 private static final ExecutorService worker=Executors.newSingleThreadExecutor();private TextView status;private EditText server,code;private CheckBox notes,reader;private TransitionController controller;private static volatile boolean busy;private static java.lang.ref.WeakReference<MainActivity> active=new java.lang.ref.WeakReference<>(null);private LinearLayout layout;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);active=new java.lang.ref.WeakReference<>(this);controller=new TransitionController(this);ScrollView scroll=new ScrollView(this);layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);int pad=(int)(20*getResources().getDisplayMetrics().density);layout.setPadding(pad,pad,pad,pad);scroll.addView(layout);setContentView(scroll);TextView title=new TextView(this);title.setText("PowerSync");title.setTextSize(30);layout.addView(title);TextView intro=new TextView(this);intro.setText("Connect native BOOX synchronization to your Alexandria server. Your previous configuration is saved before switching.");layout.addView(intro);status=new TextView(this);status.setTextSize(17);status.setPadding(0,pad,0,pad);layout.addView(status);server=new EditText(this);server.setHint("https://alexandria.example.com");server.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);layout.addView(server);code=new EditText(this);code.setHint("Enrollment code from Alexandria");code.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);layout.addView(code);notes=new CheckBox(this);notes.setText("Enable native notebook sync");layout.addView(notes);reader=new CheckBox(this);reader.setText("Enable native reading sync");layout.addView(reader);TextView scope=new TextView(this);scope.setText("PowerSync keeps your existing BOOX library identity. Enable notebook and reading sync to send eligible content to Alexandria; initial synchronization can take time.");layout.addView(scope);
 button("Grant native configuration file access",()->startActivity(new Intent(Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION,Uri.parse("package:"+getPackageName()))));button("Enroll this device",()->{String url=server.getText().toString(),secret=code.getText().toString();run(()->{JSONObject preview=controller.enroll(SafeURL.base(url),secret);runOnUiThread(()->code.setText(""));return "Enrolled with "+preview.getString("serverURL")+". Review the sync choices, then connect.";});});button("Connect to enrolled server",()->new AlertDialog.Builder(this).setTitle("Connect native sync?").setMessage("PowerSync will pause native synchronization, save the previous server configuration and sign in to your enrolled server. Existing notes remain on this device.").setPositiveButton("Connect",(d,w)->{boolean n=notes.isChecked(),r=reader.isChecked();run(()->{controller.connect(n,r);return "Connected. Native application status is reported separately from transport.";});}).setNegativeButton("Cancel",null).show());button("Return to previous server",()->new AlertDialog.Builder(this).setTitle("Return to previous server?").setMessage("Restore the saved native configuration. This works without contacting your custom server. Native sign-in may still be needed.").setPositiveButton("Restore",(d,w)->run(()->{controller.restore();return describe(controller.status());})).setNegativeButton("Cancel",null).show());button("Refresh device status",()->run(()->describe(controller.status())));button("Check server recovery status",()->run(()->controller.recoveryStatus().optString("summary","Server status received; native application may remain unverified.")));button("Recover notebook audio",this::showAudioRecovery);button("Open native BOOX settings",()->{Intent i=getPackageManager().getLaunchIntentForPackage("com.onyx");if(i!=null)startActivity(i);else startActivity(new Intent(Settings.ACTION_SETTINGS));});if(busy)status.setText("Working…");else run(()->describe(controller.status()));}

 private void showAudioRecovery(){run(()->{
  JSONArray items=controller.audioRecoveries();if(items.length()==0)return "No published MP3 repairs are available. In Alexandria, open the affected notebook and choose Recover audio to review and publish a repair first.";
  String[] labels=new String[items.length()];for(int i=0;i<labels.length;i++){JSONObject v=items.getJSONObject(i);labels[i]=v.getString("title")+" — "+v.getString("fileName");}
  runOnUiThread(()->{if(isDestroyed())return;new AlertDialog.Builder(this).setTitle("Choose a repaired recording").setItems(labels,(d,n)->{try{reviewAudio(items.getJSONObject(n).getString("operationId"));}catch(JSONException e){status.setText("Invalid recovery list");}}).setNegativeButton("Cancel",null).show();});
  return "Choose a recording to check its local copy.";
 });}
 private void reviewAudio(String operation){run(()->{
  AudioCacheRepair repair=controller.audioPacket(operation);String result=controller.inspectAudio(repair);
  if("healthy".equals(result))return "This recording already matches the original bytes. No changes needed.";
  if("missing".equals(result))return "This recording is not stored locally. Open the notebook and use native Notes sync to download the corrected server copy.";
  if(!"repairable".equals(result))return "The local recording does not exactly match the known decoding defect. Nothing changed; review it before attempting recovery.";
  runOnUiThread(()->{if(isDestroyed())return;new AlertDialog.Builder(this).setTitle("Recover this recording?").setMessage("Stop any recording and close the notebook first. PowerSync will save a private backup and replace only this verified damaged MP3. Keep Notes closed until recovery finishes.").setPositiveButton("Recover",(d,w)->run(()->{controller.repairAudio(repair);return "Recording recovered and verified against the original bytes. The previous file is retained in PowerSync’s private backup storage. You can reopen the notebook and check playback.";})).setNegativeButton("Cancel",null).show();});
  return "The local MP3 exactly matches the known decoding defect. Ready for recovery.";
 });}
 private interface Work {String call()throws Exception;}
 private void button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setOnClickListener(v->{if(!busy)action.run();});layout.addView(b);}
 private void run(Work work){if(busy)return;busy=true;status.setText("Working…");worker.execute(()->{String result;try{result=work.call();}catch(Exception e){result="PowerSync stopped safely: "+safe(e)+"\nSaved configuration and local data are retained.";}String text=result;runOnUiThread(()->{busy=false;MainActivity visible=active.get();if(visible!=null&&!visible.isDestroyed())visible.status.setText(text);});});}
 private static String safe(Exception e){Throwable t=e;while(t.getCause()!=null)t=t.getCause();if(t instanceof java.io.IOException)return t.getMessage()==null?"Native or server operation unavailable":t.getMessage();return "Operation could not complete ("+t.getClass().getSimpleName()+")";}
 private static String describe(JSONObject s)throws Exception {JSONObject f=s.getJSONObject("flags");return "Native server: "+s.getString("clusterId")+"\nNative account: "+(s.getBoolean("accountLoggedIn")?"signed in":"signed out")+"\nNotebook sync: "+f.getString("notes")+" · Reader sync: "+f.getString("reader")+"\nSetup: "+s.getString("phase")+"\nPrevious configuration saved: "+s.getBoolean("hasBaseline")+"\nNative editor application: not verified";}
 @Override protected void onDestroy(){if(active.get()==this)active.clear();super.onDestroy();}
}
